function check([str1, str2], actual, expected) {
  if (typeof actual !== 'string' || actual.length !== expected.length) return false;
  const contains = word => {
    let k = 0;
    for (const ch of actual) if (k < word.length && ch === word[k]) k++;
    return k === word.length;
  };
  return contains(str1) && contains(str2);
}

