function validate([str1, str2]) {
  for (const [name, text] of [['str1', str1], ['str2', str2]]) {
    if (typeof text !== 'string' || text.length < 1 || text.length > 1000) return `${name} needs 1 to 1000 characters.`;
    if (!/^[a-z]+$/.test(text)) return `${name} may contain only lowercase English letters.`;
  }
  return null;
}

