function shortestCommonSupersequence(str1, str2) {
  // Shortest supersequence of the suffixes str1[a..] and str2[b..], built directly as strings.
  const memo = new Map();
  const best = (a, b) => {
    if (a === str1.length) return str2.slice(b);
    if (b === str2.length) return str1.slice(a);
    const key = a * 2000 + b;
    if (memo.has(key)) return memo.get(key);
    let answer;
    if (str1[a] === str2[b]) answer = str1[a] + best(a + 1, b + 1);
    else {
      const first = str1[a] + best(a + 1, b);
      const second = str2[b] + best(a, b + 1);
      answer = first.length <= second.length ? first : second;
    }
    memo.set(key, answer);
    return answer;
  };
  return best(0, 0);
}

