function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const k = size === 'large' ? [2, 4, 26][Math.floor(rand() * 3)] : 1 + Math.floor(rand() * 3);
  const word = length => Array.from({ length }, () => letters[Math.floor(rand() * k)]).join('');
  const length = () => (size === 'large' ? 700 + Math.floor(rand() * 301) : 1 + Math.floor(rand() * 7));
  const str1 = word(length());
  if (rand() < 0.5) return [str1, word(length())];
  // Derive str2 from str1 by deleting and inserting letters, so the two share a long common subsequence.
  let str2 = '';
  for (const ch of str1) {
    if (rand() < 0.75) str2 += ch;
    if (rand() < 0.2) str2 += word(1);
  }
  if (str2.length === 0) str2 = word(1);
  return [str1, str2.slice(0, 1000)];
}
